-- ticket: the Trade Request service's records move into AoA's database, in their own schema.
-- Tables generated by scripts/trade-requests/build-trade-request-schema.sh from trade-request d41b6c9
-- (14 non-MCP tables; session, oauth_* and mcp_* stay with the standalone service). All tables start
-- empty; scripts/trade-requests/copy.ts moves and verifies rows. No table outside the 14 may reference
-- them by foreign key (the copy engine refuses to run if one does).
-- trade_request.mcp_access depends on app."User".email and .role: a later migration that rebuilds the
-- Role enum or those columns must drop and recreate the view.
-- trade_request_mcp_ro is a Terraform-managed login on Cloud SQL; the guard fails closed there and creates
-- the role only on local/CI Postgres.
BEGIN;

-- guard:begin
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'trade_request_mcp_ro') THEN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'cloudsqlsuperuser') THEN
      RAISE EXCEPTION 'trade_request_mcp_ro must be provisioned by Terraform before the trade_request schema migration';
    END IF;
    CREATE ROLE trade_request_mcp_ro LOGIN;
  END IF;
END $$;
-- guard:end

CREATE SCHEMA trade_request;

CREATE TABLE trade_request.account_exclusions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id character varying(100) NOT NULL,
    ticker character varying(20) NOT NULL,
    kind character varying(20) NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    no_buy boolean DEFAULT true NOT NULL,
    no_sell boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_by_name character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT account_exclusions_at_least_one_side CHECK ((no_buy OR no_sell)),
    CONSTRAINT account_exclusions_kind_check CHECK (((kind)::text = ANY ((ARRAY['advisor'::character varying, 'client'::character varying])::text[])))
);

CREATE TABLE trade_request.accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id character varying(50) NOT NULL,
    account_number character varying(100) NOT NULL,
    account_type character varying(50) NOT NULL,
    balance numeric(15,2) DEFAULT 0 NOT NULL,
    cash_holding numeric(15,2) DEFAULT 0 NOT NULL,
    fixed_holding numeric(15,2) DEFAULT 0 NOT NULL,
    equity_holding numeric(15,2) DEFAULT 0 NOT NULL,
    CONSTRAINT accounts_account_type_check CHECK (((account_type)::text = ANY ((ARRAY['Taxable'::character varying, 'Joint'::character varying, 'Traditional IRA'::character varying, 'Roth IRA'::character varying])::text[])))
);

CREATE TABLE trade_request.audit_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id character varying(50) NOT NULL,
    user_name character varying(255) NOT NULL,
    action character varying(255) NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    user_id uuid,
    channel character varying(20) DEFAULT 'standalone'::character varying NOT NULL,
    CONSTRAINT audit_logs_channel_check CHECK (((channel)::text = ANY ((ARRAY['standalone'::character varying, 'aoa'::character varying])::text[])))
);

CREATE TABLE trade_request.client_exclusions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id character varying(100) NOT NULL,
    ticker character varying(20) NOT NULL,
    kind character varying(20) NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    created_by uuid,
    created_by_name character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    no_buy boolean DEFAULT true NOT NULL,
    no_sell boolean DEFAULT true NOT NULL,
    CONSTRAINT client_exclusions_at_least_one_side CHECK ((no_buy OR no_sell)),
    CONSTRAINT client_exclusions_kind_check CHECK (((kind)::text = ANY ((ARRAY['advisor'::character varying, 'client'::character varying])::text[])))
);

CREATE TABLE trade_request.clients (
    id character varying(50) NOT NULL,
    name character varying(255) NOT NULL
);

CREATE TABLE trade_request.digest_runs (
    run_date date NOT NULL,
    posted_at timestamp with time zone DEFAULT now() NOT NULL,
    summary jsonb NOT NULL
);

CREATE TABLE trade_request.drift_alert_sends (
    run_date_local date NOT NULL,
    sent_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE trade_request.drift_status_overrides (
    account_id character varying(100) NOT NULL,
    reason text NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    expires_on date,
    set_by uuid,
    set_by_name character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recheck_notified_at timestamp with time zone,
    CONSTRAINT drift_status_overrides_reason_check CHECK ((reason = ANY (ARRAY['asset_location'::text, 'tax_constraint'::text, 'active_transition'::text, 'intentional_cash'::text, 'concentrated_position'::text, 'template_error'::text, 'direct_index_noise'::text, 'other'::text])))
);

CREATE TABLE trade_request.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    body text NOT NULL,
    request_id character varying(50),
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE trade_request.position_drift_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_date_local date NOT NULL,
    run_started_at timestamp with time zone DEFAULT now() NOT NULL,
    account_id text NOT NULL,
    account_title text DEFAULT ''::text NOT NULL,
    household_name text DEFAULT ''::text NOT NULL,
    coverage text NOT NULL,
    status text NOT NULL,
    total_value_usd numeric(18,2) DEFAULT 0 NOT NULL,
    position_cash_pct numeric(7,4) DEFAULT 0 NOT NULL,
    position_fixed_pct numeric(7,4) DEFAULT 0 NOT NULL,
    position_equity_pct numeric(7,4) DEFAULT 0 NOT NULL,
    template_cash_pct numeric(7,4) DEFAULT 0 NOT NULL,
    template_fixed_pct numeric(7,4) DEFAULT 0 NOT NULL,
    template_equity_pct numeric(7,4) DEFAULT 0 NOT NULL,
    max_bucket_delta_pct numeric(7,4) DEFAULT 0,
    worst_bucket text,
    symbol_breach_count integer DEFAULT 0 NOT NULL,
    tolerance_pct numeric(7,4) DEFAULT 5 NOT NULL,
    uninvested_cash_threshold_pct numeric(7,4) DEFAULT 99 NOT NULL,
    schema_version integer NOT NULL,
    snapshot_source text NOT NULL,
    snapshot_as_of timestamp with time zone,
    details jsonb NOT NULL,
    CONSTRAINT position_drift_accounts_account_id_check CHECK ((length(TRIM(BOTH FROM account_id)) > 0)),
    CONSTRAINT position_drift_accounts_coverage_check CHECK ((coverage = ANY (ARRAY['both'::text, 'positions_only'::text, 'template_only'::text, 'unmapped'::text]))),
    CONSTRAINT position_drift_accounts_status_check CHECK ((status = ANY (ARRAY['in'::text, 'out'::text, 'uninvested'::text, 'no_template'::text, 'negligible'::text, 'template_invalid'::text]))),
    CONSTRAINT position_drift_accounts_symbol_breach_count_check CHECK ((symbol_breach_count >= 0)),
    CONSTRAINT position_drift_accounts_worst_bucket_check CHECK (((worst_bucket IS NULL) OR (worst_bucket = ANY (ARRAY['cash'::text, 'fixed'::text, 'equity'::text]))))
);

CREATE TABLE trade_request.registry_drift_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_date_local date NOT NULL,
    run_started_at timestamp with time zone DEFAULT now() NOT NULL,
    household_name text NOT NULL,
    account_count integer NOT NULL,
    max_delta_pct numeric(7,4) NOT NULL,
    breach boolean NOT NULL,
    coverage_status text NOT NULL,
    schema_version integer NOT NULL,
    snapshot_source text NOT NULL,
    snapshot_as_of timestamp with time zone,
    details jsonb NOT NULL,
    CONSTRAINT registry_drift_runs_account_count_check CHECK ((account_count >= 0)),
    CONSTRAINT registry_drift_runs_coverage_status_check CHECK ((coverage_status = ANY (ARRAY['full'::text, 'partial'::text, 'engine_only'::text, 'meridian_only'::text, 'unmapped_account'::text]))),
    CONSTRAINT registry_drift_runs_household_name_check CHECK ((length(TRIM(BOTH FROM household_name)) > 0))
);

CREATE TABLE trade_request.security_sector (
    ticker text NOT NULL,
    source_symbol text,
    name text,
    sic_code text,
    sic_description text,
    sector text,
    source text NOT NULL,
    resolved boolean DEFAULT false NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_attempt_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    category text,
    asset_class text,
    instrument_kind text,
    CONSTRAINT security_sector_attempts_check CHECK ((attempts >= 0))
);

CREATE TABLE trade_request.trade_requests (
    id character varying(50) NOT NULL,
    client_id character varying(100) NOT NULL,
    advisor_id uuid,
    trade_type character varying(100) NOT NULL,
    trade_amount character varying(100),
    deposit_account character varying(100),
    rebalance_all boolean DEFAULT false NOT NULL,
    status character varying(100) DEFAULT 'Pending Review'::character varying NOT NULL,
    total_value numeric(15,2),
    selected_accounts text[] DEFAULT '{}'::text[] NOT NULL,
    priority character varying(20),
    advisor_notes text,
    residence character varying(50),
    liquidation_approval boolean,
    advisor_exclusions text,
    client_exclusions text,
    esg_filters jsonb,
    risk_profile integer,
    base_allocation jsonb,
    equity_strategies jsonb,
    raise_cash_reason text,
    liquidity_deadline date,
    liquidate_option character varying(50),
    liquidate_positions text,
    execution_plan jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    client_name character varying(255),
    account_metadata jsonb,
    client_ids jsonb,
    client_names jsonb,
    idempotency_key uuid,
    asset_location_mode text DEFAULT 'priority'::text NOT NULL,
    household_id bigint,
    household_name text,
    preapproval_checklist jsonb,
    CONSTRAINT trade_requests_asset_location_mode_check CHECK ((asset_location_mode = ANY (ARRAY['priority'::text, 'mirror'::text]))),
    CONSTRAINT trade_requests_household_id_name_paired CHECK (((household_id IS NULL) = (household_name IS NULL))),
    CONSTRAINT trade_requests_priority_check CHECK (((priority)::text = ANY ((ARRAY['Urgent'::character varying, 'Standard'::character varying, 'Low'::character varying])::text[]))),
    CONSTRAINT trade_requests_status_check CHECK (((status)::text = ANY ((ARRAY['Pending Review'::character varying, 'Needs Info'::character varying, 'Pending Current Asset Liquidation'::character varying, 'Approved'::character varying, 'Rejected'::character varying, 'Completed'::character varying])::text[]))),
    CONSTRAINT trade_requests_trade_type_check CHECK (((trade_type)::text = ANY ((ARRAY['Initial Funding'::character varying, 'Rebalance'::character varying, 'Cash Deposit'::character varying, 'Raise Cash'::character varying, 'Liquidate'::character varying])::text[])))
);

CREATE TABLE trade_request.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    google_id character varying(255),
    email character varying(255) NOT NULL,
    name character varying(255) NOT NULL,
    picture text,
    role character varying(50) DEFAULT 'advisor'::character varying NOT NULL,
    slack_user_id character varying(50),
    is_active boolean DEFAULT true NOT NULL,
    last_login timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    theme_preference character varying(10) DEFAULT 'system'::character varying NOT NULL,
    aoa_provisioned_at timestamp with time zone,
    CONSTRAINT chk_users_theme CHECK (((theme_preference)::text = ANY ((ARRAY['light'::character varying, 'dark'::character varying, 'system'::character varying])::text[]))),
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['advisor'::character varying, 'trader'::character varying])::text[])))
);

ALTER TABLE ONLY trade_request.account_exclusions
    ADD CONSTRAINT account_exclusions_account_id_ticker_kind_key UNIQUE (account_id, ticker, kind);

ALTER TABLE ONLY trade_request.account_exclusions
    ADD CONSTRAINT account_exclusions_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.accounts
    ADD CONSTRAINT accounts_account_number_key UNIQUE (account_number);

ALTER TABLE ONLY trade_request.accounts
    ADD CONSTRAINT accounts_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.audit_logs
    ADD CONSTRAINT audit_logs_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.client_exclusions
    ADD CONSTRAINT client_exclusions_client_id_ticker_kind_key UNIQUE (client_id, ticker, kind);

ALTER TABLE ONLY trade_request.client_exclusions
    ADD CONSTRAINT client_exclusions_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.clients
    ADD CONSTRAINT clients_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.digest_runs
    ADD CONSTRAINT digest_runs_pkey PRIMARY KEY (run_date);

ALTER TABLE ONLY trade_request.drift_alert_sends
    ADD CONSTRAINT drift_alert_sends_pkey PRIMARY KEY (run_date_local);

ALTER TABLE ONLY trade_request.drift_status_overrides
    ADD CONSTRAINT drift_status_overrides_pkey PRIMARY KEY (account_id);

ALTER TABLE ONLY trade_request.notifications
    ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.position_drift_accounts
    ADD CONSTRAINT position_drift_accounts_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.position_drift_accounts
    ADD CONSTRAINT position_drift_accounts_run_date_local_account_id_key UNIQUE (run_date_local, account_id);

ALTER TABLE ONLY trade_request.registry_drift_runs
    ADD CONSTRAINT registry_drift_runs_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.registry_drift_runs
    ADD CONSTRAINT registry_drift_runs_run_date_local_household_name_key UNIQUE (run_date_local, household_name);

ALTER TABLE ONLY trade_request.security_sector
    ADD CONSTRAINT security_sector_pkey PRIMARY KEY (ticker);

ALTER TABLE ONLY trade_request.trade_requests
    ADD CONSTRAINT trade_requests_pkey PRIMARY KEY (id);

ALTER TABLE ONLY trade_request.users
    ADD CONSTRAINT users_email_key UNIQUE (email);

ALTER TABLE ONLY trade_request.users
    ADD CONSTRAINT users_google_id_key UNIQUE (google_id);

ALTER TABLE ONLY trade_request.users
    ADD CONSTRAINT users_pkey PRIMARY KEY (id);

CREATE INDEX idx_account_exclusions_account_id ON trade_request.account_exclusions USING btree (account_id);

CREATE INDEX idx_accounts_client ON trade_request.accounts USING btree (client_id);

CREATE INDEX idx_audit_created ON trade_request.audit_logs USING btree (created_at DESC);

CREATE INDEX idx_audit_request ON trade_request.audit_logs USING btree (request_id);

CREATE INDEX idx_audit_user_id ON trade_request.audit_logs USING btree (user_id);

CREATE INDEX idx_client_exclusions_client_id ON trade_request.client_exclusions USING btree (client_id);

CREATE INDEX idx_notifications_user_created ON trade_request.notifications USING btree (user_id, created_at DESC);

CREATE INDEX idx_notifications_user_unread ON trade_request.notifications USING btree (user_id) WHERE (read_at IS NULL);

CREATE INDEX idx_pda_household ON trade_request.position_drift_accounts USING btree (household_name, run_date_local DESC);

CREATE INDEX idx_pda_run_date_status ON trade_request.position_drift_accounts USING btree (run_date_local DESC, status);

CREATE INDEX idx_registry_drift_runs_breach ON trade_request.registry_drift_runs USING btree (run_date_local DESC) WHERE breach;

CREATE INDEX idx_registry_drift_runs_household ON trade_request.registry_drift_runs USING btree (household_name, run_date_local DESC);

CREATE INDEX idx_requests_advisor ON trade_request.trade_requests USING btree (advisor_id);

CREATE INDEX idx_requests_client ON trade_request.trade_requests USING btree (client_id);

CREATE INDEX idx_requests_client_ids ON trade_request.trade_requests USING gin (client_ids jsonb_path_ops);

CREATE INDEX idx_requests_created ON trade_request.trade_requests USING btree (created_at DESC);

CREATE INDEX idx_requests_status ON trade_request.trade_requests USING btree (status);

CREATE INDEX idx_security_sector_asset_class ON trade_request.security_sector USING btree (asset_class) WHERE (asset_class IS NOT NULL);

CREATE INDEX idx_security_sector_unresolved ON trade_request.security_sector USING btree (resolved, attempts);

CREATE UNIQUE INDEX idx_trade_requests_idempotency ON trade_request.trade_requests USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL);

CREATE INDEX idx_users_email ON trade_request.users USING btree (email);

CREATE INDEX idx_users_google_id ON trade_request.users USING btree (google_id);

CREATE INDEX idx_users_lower_email ON trade_request.users USING btree (lower((email)::text));

ALTER TABLE ONLY trade_request.account_exclusions
    ADD CONSTRAINT account_exclusions_created_by_fkey FOREIGN KEY (created_by) REFERENCES trade_request.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY trade_request.accounts
    ADD CONSTRAINT accounts_client_id_fkey FOREIGN KEY (client_id) REFERENCES trade_request.clients(id);

ALTER TABLE ONLY trade_request.audit_logs
    ADD CONSTRAINT audit_logs_request_id_fkey FOREIGN KEY (request_id) REFERENCES trade_request.trade_requests(id) ON DELETE CASCADE;

ALTER TABLE ONLY trade_request.audit_logs
    ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES trade_request.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY trade_request.client_exclusions
    ADD CONSTRAINT client_exclusions_created_by_fkey FOREIGN KEY (created_by) REFERENCES trade_request.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY trade_request.drift_status_overrides
    ADD CONSTRAINT drift_status_overrides_set_by_fkey FOREIGN KEY (set_by) REFERENCES trade_request.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY trade_request.notifications
    ADD CONSTRAINT notifications_request_id_fkey FOREIGN KEY (request_id) REFERENCES trade_request.trade_requests(id) ON DELETE SET NULL;

ALTER TABLE ONLY trade_request.notifications
    ADD CONSTRAINT notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES trade_request.users(id) ON DELETE CASCADE;

ALTER TABLE ONLY trade_request.trade_requests
    ADD CONSTRAINT trade_requests_advisor_id_fkey FOREIGN KEY (advisor_id) REFERENCES trade_request.users(id);


CREATE TABLE trade_request.serving_state (
    id             BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (id),
    serving_source TEXT NOT NULL DEFAULT 'standalone' CHECK (serving_source IN ('standalone', 'aoa')),
    digest_sender  TEXT NOT NULL DEFAULT 'standalone' CHECK (digest_sender IN ('standalone', 'aoa')),
    drift_sender   TEXT NOT NULL DEFAULT 'standalone' CHECK (drift_sender IN ('standalone', 'aoa')),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by     TEXT NOT NULL DEFAULT 'migration'
);
INSERT INTO trade_request.serving_state (id) VALUES (TRUE);

CREATE TABLE trade_request.serving_state_transitions (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    actor      TEXT NOT NULL,
    from_state JSONB NOT NULL,
    to_state   JSONB NOT NULL,
    reason     TEXT NOT NULL
);

CREATE TABLE trade_request.copy_runs (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mode                    TEXT NOT NULL CHECK (mode IN ('full', 'change', 'report', 'copy_back')),
    actor                   TEXT NOT NULL,
    started_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    finished_at             TIMESTAMPTZ,
    verdict                 TEXT CHECK (verdict IN ('passed', 'blocked', 'report_only', 'refused', 'failed')),
    serving_source_at_start TEXT NOT NULL,
    kinds                   JSONB NOT NULL DEFAULT '[]'::jsonb,
    error                   TEXT
);
CREATE INDEX copy_runs_started_at_idx ON trade_request.copy_runs (started_at DESC);

-- MCP role check: whether a normalized email's AOA account currently grants Trade Request access, and whether its
-- role maps to the standalone trader role (ADMIN or OPERATIONS; ticket uses it for MCP's ownership checks).
CREATE VIEW trade_request.mcp_access AS
SELECT lower(btrim(u.email)) AS email,
       bool_or(u.role IN ('ADMIN', 'OPERATIONS', 'ADVISOR')) AS has_access,
       bool_or(u.role IN ('ADMIN', 'OPERATIONS')) AS trader_role
  FROM app."User" u
 WHERE u.email IS NOT NULL
 GROUP BY lower(btrim(u.email));

-- app_rw (AoA runtime): read/write the record tables; read the serving state and ledger.
GRANT USAGE ON SCHEMA trade_request TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON
    trade_request.users, trade_request.clients, trade_request.accounts, trade_request.trade_requests,
    trade_request.audit_logs, trade_request.notifications, trade_request.client_exclusions,
    trade_request.account_exclusions, trade_request.digest_runs, trade_request.registry_drift_runs,
    trade_request.position_drift_accounts, trade_request.drift_alert_sends, trade_request.drift_status_overrides,
    trade_request.security_sector
  TO app_rw;
GRANT SELECT ON trade_request.serving_state, trade_request.serving_state_transitions, trade_request.copy_runs TO app_rw;

-- trade_request_mcp_ro (standalone MCP): read-only on what MCP reads; nothing else.
GRANT USAGE ON SCHEMA trade_request TO trade_request_mcp_ro;
GRANT SELECT ON
    trade_request.trade_requests, trade_request.audit_logs, trade_request.users, trade_request.accounts,
    trade_request.clients, trade_request.client_exclusions, trade_request.account_exclusions,
    trade_request.serving_state, trade_request.mcp_access
  TO trade_request_mcp_ro;

COMMIT;
